#!/bin/bash
set -euo pipefail

PADLOCK_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
PADLOCK_VERSION="$(tr -d '\n\r' < "$PADLOCK_ROOT/VERSION")"
PADLOCK_DIST="$PADLOCK_ROOT/dist"
PADLOCK_STAGE="$PADLOCK_ROOT/build/dmg-stage"
PADLOCK_NAME="Padlock-$PADLOCK_VERSION-universal"

"$PADLOCK_ROOT/scripts/build.sh" universal
mkdir -p "$PADLOCK_STAGE"
# Refresh only the known staging entries generated by this script.
rm -rf "$PADLOCK_STAGE/Padlock.app"
rm -f "$PADLOCK_STAGE/Applications" "$PADLOCK_STAGE/READ ME FIRST.txt" "$PADLOCK_STAGE/LICENSE"
/usr/bin/ditto "$PADLOCK_DIST/Padlock.app" "$PADLOCK_STAGE/Padlock.app"
ln -s /Applications "$PADLOCK_STAGE/Applications"
cp "$PADLOCK_ROOT/LICENSE" "$PADLOCK_STAGE/LICENSE"
cp "$PADLOCK_ROOT/docs/INSTALL.txt" "$PADLOCK_STAGE/READ ME FIRST.txt"

/usr/bin/ditto -c -k --sequesterRsrc --keepParent \
    "$PADLOCK_DIST/Padlock.app" "$PADLOCK_DIST/$PADLOCK_NAME.zip"
/usr/bin/hdiutil create -volname "Padlock $PADLOCK_VERSION" -srcfolder "$PADLOCK_STAGE" \
    -ov -format UDZO -fs HFS+ "$PADLOCK_DIST/$PADLOCK_NAME.dmg"
/usr/bin/hdiutil verify "$PADLOCK_DIST/$PADLOCK_NAME.dmg"
cd "$PADLOCK_DIST"
/usr/bin/shasum -a 256 "$PADLOCK_NAME.zip" "$PADLOCK_NAME.dmg" > SHA256SUMS.txt
printf 'Release downloads:\n%s\n%s\n%s\n' \
    "$PADLOCK_DIST/$PADLOCK_NAME.zip" "$PADLOCK_DIST/$PADLOCK_NAME.dmg" "$PADLOCK_DIST/SHA256SUMS.txt"
